<?php
require __DIR__.'/app/bootstrap.php';require_login();require __DIR__.'/app/layout.php';$q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$sql="SELECT c.*,a.applicant_no,a.first_name,a.last_name FROM id_cards c JOIN applicants a ON a.id=c.applicant_id WHERE 1=1";$params=[];if($q!==''){$sql.=' AND (c.card_number LIKE ? OR a.applicant_no LIKE ? OR a.first_name LIKE ? OR a.last_name LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}if(in_array($status,['Pending','Printed','Issued','Lost','Expired','Cancelled'],true)){$sql.=' AND c.status=?';$params[]=$status;}$sql.=' ORDER BY c.created_at DESC';$st=$pdo->prepare($sql);$st->execute($params);$cards=$st->fetchAll();page_header('National ID cards'); ?>
<div class="panel"><form class="searchbar" method="get"><label class="search-field">Search cards<input name="q" value="<?=e($q)?>" placeholder="Card number, applicant name or number"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(['Pending','Printed','Issued','Lost','Expired','Cancelled'] as $s): ?><option <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select></label><button class="btn primary">Search</button></form><div class="panel-heading"><div><h2>Card issuance records</h2><p class="muted"><?=count($cards)?> card record(s)</p></div><a class="btn primary" href="card_form.php">＋ Record card</a></div><div class="table-wrap"><table><thead><tr><th>Card number</th><th>Applicant</th><th>Issue date</th><th>Expiry date</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($cards as $c): ?><tr><td><strong><?=e($c['card_number'])?></strong></td><td><a href="applicant_view.php?id=<?=(int)$c['applicant_id']?>"><?=e($c['first_name'].' '.$c['last_name'])?></a><small class="table-sub"><?=e($c['applicant_no'])?></small></td><td><?=e($c['issue_date']?:'—')?></td><td><?=e($c['expiry_date']?:'—')?></td><td><span class="pill"><?=e($c['status'])?></span></td><td><a href="card_form.php?id=<?=(int)$c['id']?>">Edit</a></td></tr><?php endforeach; if(!$cards): ?><tr><td colspan="6" class="empty">No card records found.</td></tr><?php endif; ?></tbody></table></div></div><?php page_footer(); ?>
